parameters.jsCode:
const d = $input.first().json;
const body = d.body ?? d;
const draft = body.draft ?? {};
return [{
  json: {
    userId: $json.userId ?? null,
    timestamp: new Date().toISOString(),
    topic: body.topic ?? $json.topic ?? '',
    source: body.source ?? 'local',
    headline: draft.headline ?? '',
    script: draft.script ?? '',
    tags: draft.tags ?? [],
    cta: draft.cta ?? '',
    estimatedReadMinutes: draft.estimatedReadMinutes ?? null,
    research: Array.isArray(body.research) ? body.research.map((r) => ({ title: r.title ?? '', date: r.date ?? '' })) : []
  }
}];

